export default function createRandomPolicyTags(tagListName: string, numberOfTags = 0): PolicyTagLists {
    const tags: PolicyTags = {};
    for (let i = 0; i < numberOfTags; i++) {
        const tagName = randWord();
        tags[tagName] = {
            name: tagName,
            enabled: true,
        };
    }

    return {
        [tagListName]: {
            name: tagListName,
            orderWeight: 0,
            required: false,
            tags,
        },
    };
